DEBT = f'{ROOT}/World/step9/COMPILE_DEBT.md'; MM = f'{MEM}/MEMORY.md'; MW = f'{MEM}/deuteronomy-walk.md'
def sub1(t, a, b, name):
    assert t.count(a) == 1, (name, t.count(a), a[:70]); return t.replace(a, b)
def span1(t, a, b, new, name):
    i = t.find(a); assert i >= 0 and t.count(a) == 1, (name, 'start', t.count(a)); j = t.find(b, i); assert j > i and t.count(b) == 1, (name, 'end', t.count(b)); return t[:i] + new + t[j + len(b):]
print('THE PRINTS:', {k: (v if len(str(v)) < 90 else str(v)[:87] + '...') for k, v in D.items() if k != 'TABLE'})
ASB = '\n\n' + rd(f'{SP}/ch33b_asbuilt.txt') % D
NOTE242 = (" — THE TAIL OF 21b (2026-09-29, after the compaction at #242, on the owner's \"reread and go\"): the chain's first SUMMARY read once — ONE STEP RED (the probes: the import cache %(IC1)s — %(C6)s; %(C6G)s; every other suite green — %(PROBES1)s; the tape, the daemon, dependency, build, journal and register --strict gates PASS; the long steps skipped; %(CHAIN1)d s); THE CAUSE READ IN THE CACHE'S OWN INDEX FILES before the clear (%(IDX)s): the new runner HARVESTED ALONE at the tape step's warm run beside the older runners restored from their blobs — its bindings already assignments (20b's lesson 19 built in), the objects it bound the restored copies nested in the callees' DATA, under no top-level name, so its records hold plain hashes where the song's hold aliases (18b's lesson 11's harvest half — met by a NEW runner, not an edited one: every compile adds a runner, every compile clears the cache whole before the chain); THE TAIL JOB in one background wrapper (ch33b_tail_chain.sh — the cache cleared whole, the chain's second pass, one DONE file): its first launch --from probes STOPPED at %(ABORT_S)d s — the chain's probes step launches its eleven suites AT ONCE, on a cold cache a race (a suite restoring what a faster sibling wrote, then harvesting the rest alone beside restored neighbours — the fault itself); the cache cleared a second time (%(NCLEARS)d clears timed) and the pass relaunched FROM THE TAPE, 20b's form (the tape's one process harvests the cache whole in the sequence's order before the suites); THE SECOND PASS (%(CHAIN2)d s) GREEN THROUGH THE POSITIONS (the tape %(TAPE2)s in %(TAPE2_S)d s with the harvest inside it; the probe suites %(PROBES)s — the cache probe %(IC2)s, %(C6OK)s kept, %(ICLOAD2)s; the register gate --strict %(REG60)s; the positions %(POS)s in %(POS_S)d s — the tenfold finding unchanged, OWED a measurement) AND RED AT THE CHECKPOINT PROBES (%(CK2)s — K1 %(K1D)s, the index DO1's): THE CAUSE READ BY HAND (ch33b_k1_diag.py — K1's steps repeated: the probe's beyond_the_tape finds the tape's last verse by a single-quote regex and returned %(BEYOND1)s; every one of chapter 33's %(DQ)d case sources carries an apostrophe and sits in the tape literal in double quotes by repr, so run_to stopped at 33:1 with no chapter 33 line and %(DIFFS)s; the positions' finals MATCH, the tape's run 10/10); THE PROBE'S READER WIDENED to either quote (patch_k1_probe_ch33b.py — %(PK)s; no runner, registry or tape moved); THE THIRD PASS --from checkpoint ALL GREEN (%(CHAIN3)d s; the checkpoint probes %(CK3)s; the stamp; the sweep %(SWEEP)s in %(SWEEP_S)d s, this runner %(SWT)s s under INK_CACHE=0, the slowest %(SW_TOP)s — under the 2400 limit; the journal UNMOVED) — the two %(CHAIN_S)d s over %(NCHAIN)d steps, no further demand; the four records and the debt line (15) written in one call (write_ch33b_records.py; the map's AS BUILT from the template ch33b_asbuilt.txt with the departures 1-14 and the lessons 1-16), the forms copied (RUN A's, RUN B's and the tail's), the commit message at <scratch>/commit_msg_ch33b.txt (sitting 21 folded beneath 21b — uncommitted together since 472d2a3); %(NSTEP)d timed steps, %(TSEC)d machine seconds. THE COST: RUN A in the reading's tail window, RUN B one window to the chain's launch, the tail one window — the cap held at every point. NEXT ON HIS WORD: the commit (\"Commit\" = no push; \"commit push\" = both — 21 with 21b); then, after a compaction (\"Reread\", then \"Go\"), SITTING 22 — THE READING OF CHAPTER 34 (Moses' death — twelve verses; the Sifrei's piska 357 and Onkelos whole; THE THREE GIFTS' DAEMON at 34:5 designed at 22b; the pointer 33:21 -> 34:6 and the commission's debit 34:1-4 paid there; Tosefta Sotah 4:4 read there), LEAN, its measurements first — DEUTERONOMY'S LAST CHAPTER. POST-COMPACTION REREADS: the recovery page, the map's newest section (\"Sitting 21b — CHAPTER 33 — AS BUILT — LEAN\"), MEMORY.md; then this checkpoint." % D)
DEBT_LINE = (" (15) sitting 21b (2026-09-29) — CHAPTER 33 COMPILED, LEAN, ONE RUNNER OVER ONE UNIT — THE BLESSING (two runs + the tail; RUN A in the reading's tail window, the cap held): the fifteen rows the ledger cites, read whole at the design (%(NMISH)d Mishnah, %(NTOS)d Tosefta — %(EXAMROWS)s; four rows the regex misread — %(EXCL)s — read whole and excluded); NO docket, NO Talmud folio read; eleven cells and the table, %(CASES)d cases %(MATRIX)s; eleven lines in two forms one per claim (10 speech, 1 act), %(NWRITES)d writes — every one new, NO reuse — on twelve ledgers (Israel and the tribes' fathers, Dan's dan_son; Simeon none), %(PAR)s parameters; NO MARKER — Moses' last day (40, 12, 7) 19b's; %(MINE)d edges from the runner (%(MCALL)d CALL reference; %(MFALSE)d token edges FALSE by homograph — the talion's under at 33:13, the Passover's firstling at 33:17, Molech's letters in 33:5's king; the registration edge from the sequence); NO gate pointer — the readback's two pointer rows 33:5 and 33:28 PAID (grade R; 20b's owed), 33:21 FORWARD to 34:6 (Moses' grave — the death's sitting's); THE FALSE SEVEN a DATA row (33:23); THE STITCHER'S REGISTER TEST — the frame's act cites 33:5's 'and there was', the speeches the frame's 33:2 (two lines dropped on the first stitch); the tape %(VSL)s on its first run; the chain's first pass the cache probe's C6 alone RED — the NEW runner harvested alone beside cached neighbours (the cause read in the cache's index files: plain hashes where the song's are aliases; the bindings already assignments) — the cache cleared whole; the second pass's first launch from the probes stopped at %(ABORT_S)d s (eleven suites at once on a cold cache — a race), cleared again, relaunched FROM THE TAPE: green through the positions (%(POS_S)d s — the tenfold finding OWED a measurement), RED at the checkpoint probes' K1 — the probe's tape reader took single-quoted case sources alone and chapter 33's eleven carry an apostrophe (read by hand; widened to either quote); the third pass from the checkpoint ALL GREEN (sweep %(SWEEP)s); OWED: the Talmud folios the rows name (Shabbat 55; Sotah 13b-14a; Zevachim 118b; Sanhedrin 91b-92a; Avodah Zarah 2b-3a; the Jerusalem Talmud Taanit 4:2 and Sheviit 6:1), the three Tosefta parallels the export does not hold (Sotah 11:11, Eruvin 8:23, Chagigah 2:6), the readback's exercise of the blessing on the Prophets' and the Writings' tapes (Habakkuk 3:3 and 3:6, Joshua 10:24 and 14:6, Psalm 90:1, 4:6 and 51:21, 2 Kings 18:32, Isaiah 36:17, Ezra 4:3, 1 Chronicles 11:10), THE THREE GIFTS' DAEMON (34:5), the pointer rows ahead (34:1-4, 34:4, 34:6; Tosefta Sotah 4:4 left for 34), the sanctuary's tribe an OPEN parameter (352:10's dispute), the conquest's tape (Joshua's — 33:29's necks of the kings), the persons of the cases, the rest of chapter 33's glosses, the ink forms' own lint flags (ch33_ink.py's copy joins ch22, ch26, ch29 and ch32's), sitting 15's two manifests' middah strings, THE INSTALL HYPOTHESIS, the ten deferred records, the full process; the commit on his word. 22 (the reading of 34): next." % D)
# ---- the texts checked against the files ----
m = rd(MAP); _d = m.rfind('## Sitting 21b — THE COMPILE OF CHAPTER 33, THE BLESSING, Deuteronomy 33:1-29 — LEAN'); assert _d > 0 and '## Sitting 21b — CHAPTER 33 — AS BUILT' not in m and m.find('\n## ', _d + 10) < 0, 'the design the last section'
sd = rd(SD); assert '\n#242 (' in sd and 'THE TAIL OF 21b (' not in sd; i242 = sd.index('\n#242 ('); assert sd.find('\n#2', i242 + 5) < 0, '#242 the last checkpoint'
rec = rd(REC); i, j = rec.index('## 2. WHERE IT STANDS'), rec.index('## 3. THE STANDING LAWS'); assert 0 < i < j
SEC2 = ('## 2. WHERE IT STANDS (2026-09-29; #242 + its NOTE — sitting 21b DONE, newest)\n'
        '- NUMBERS CLOSED. DEUTERONOMY 1:1-33:29 ON THE TAPE (1-32 PUSHED through 472d2a3; 33 READ + COMPILED, uncommitted).\n'
        '- units 250 / standing 2371, hash 8b8fff1fa28953af. %s runners, %s daemons; %s kinds / %s effects.\n'
        '- THE TAPE at RUN (%s, pairs, 127); %s (DO1-DO5); MARKERS 173 — Moses\' last day (40, 12, 7) at 31:1, none since; checkpoint_check %s.\n'
        '- ⚠ THE LEAN PASS (#208): 16-34 lean — core shelf, 4 records, chain once; full process OWED. A MARKER or BIG-CALLEE compile splits RUN B.\n'
        '- 21 (ch 33 READ) DONE #240 (176 sources, 11 claims); 21b (ch 33 COMPILE) DONE at #242\'s NOTE: blessing_of_moses %s; %d edges; chain thrice — C6 RED (new runner harvested alone; cache cleared whole), K1 RED (the probe read single-quoted sources alone; widened), then ALL GREEN (sweep %s). NEXT: commit on his word (21 with 21b); then 22 (ch 34 — the last).\n\n'
        % (DGL, DAEM, KREG, EREG, RUN, VS[-1], CC.replace('checkpoint_check: ', ''), MATRIX, MINE, SWEEP))
rec2 = rec[:i] + SEC2 + rec[j:]; rec2 = sub1(rec2, 'cold_run_<span>.py (77 runners', 'cold_run_<span>.py (78 runners', 'the file map')
mm = rd(MM)
g = re.search(r"21b RUN A \+ B 2026-09-29 at #242 \(.*?then the commit on his word \(21 with 21b\)", mm); assert g, 'the walk line'
NEWL = "21b DONE 2026-09-29 at #242 + its NOTE (the compile — the 78th runner blessing_of_moses %s; %s kinds in two forms / %s effects — statuses on twelve ledgers, NO MARKER, no reuse; the tape %s on its first run; %d edges; the chain THREE PASSES: pass 1 the cache probe C6 alone RED — the NEW runner harvested alone beside cached neighbours (the cache cleared whole; every compile clears before its chain), pass 2 FROM THE TAPE green to the positions (its first launch from the probes stopped — eleven suites at once on a cold cache race; a pass after a clear runs from the tape), K1 RED — the checkpoint probe's tape reader took single-quoted case sources alone, chapter 33's carry an apostrophe (widened to either quote), pass 3 from the checkpoint ALL GREEN; the long form in the file), UNCOMMITTED with 21 since 472d2a3; NEXT: the commit on his word (21 with 21b), then 22 (the reading of 34, lean — DEUTERONOMY'S LAST) after a compaction" % (MATRIX, KADD, EADD, VS[-1], MINE)
mm2 = mm[:g.start()] + NEWL + mm[g.end():]
# the index under its cap: the pushed segments 16-19b shortened (their long forms in the walk file and the map)
OLD_A = "16 (ch 19-21 READ, lean) DONE 2026-09-24 (335 sources, 13 claims; FROZEN; chain green); "; OLD_B = "PUSHED c4b14ce 2026-09-27 (18b + 19 + 19b together, on 'Commit push'); "
SHORT = ("16/16b (ch 19-21 READ + COMPILED, lean — refuge_war_family 63/63) 2026-09-24/25, PUSHED; 17/17b (ch 22-25 READ + COMPILED, lean, four units — the 74th runner persons_poor_court 94/94; 36 edges) 2026-09-26, PUSHED; "
         "18 (ch 26-28 READ, lean, five units — the fold 244/2329) 2026-09-26, PUSHED 68191ea; 18b (the compile — the 75th runner firstfruits_ebal_curses 88/88; the pointer 15:6 PAID) 2026-09-27 at #226; "
         "19 (ch 29-31 READ, lean, three units — the fold 247/2344) 2026-09-27; 19b (the compile — the 76th runner covenant_return_charge 95/95; ONE MARKER at 31:1 — Moses' last day (40, 12, 7), markers 173; THE CAP BROKEN in RUN B — a marker sitting splits RUN B) 2026-09-27 at #230 — 18b + 19 + 19b PUSHED c4b14ce 2026-09-27 (the long forms in the file); ")
mm2 = span1(mm2, OLD_A, OLD_B, SHORT, 'the index segments 16-19b')
mw = rd(MW)
mw2 = sub1(mw, 'description: "SITTING 21b RUN B AT ITS CLEAN POINT 2026-09-29 (chapter 33 COMPILED lean — the 78th runner blessing_of_moses %s, 11 kinds in two forms / 28 effects on twelve ledgers, NO MARKER, no reuse, the tape 10/10, 42 edges, the chain LAUNCHED; NEXT THE TAIL then the commit on his word) — ' % MATRIX,
           'description: "SITTING 21b DONE 2026-09-29 (chapter 33 COMPILED lean — the 78th runner blessing_of_moses %s, %s kinds in two forms / %s effects on twelve ledgers, NO MARKER, no reuse, the tape %s, %d edges, the chain ALL GREEN on its third pass — the cache probe red on the first (the new runner harvested alone, the cache cleared whole), K1 red on the second (its single-quote tape reader, widened); UNCOMMITTED with 21; NEXT the commit on his word, then 22 — chapter 34, the last) — ' % (MATRIX, KADD, EADD, VS[-1], MINE), 'the description')
mw2 = mw2.rstrip('\n') + ("\n\nSITTING 21b DONE 2026-09-29 (the tail, after the compaction at #242, on \"reread and go\"): the gates chain's first pass ONE SUITE RED (%(CHAIN1)d s — the import cache %(IC1)s: C6's sharing groups — the new runner's OH_CHAIN, GR_GRAVE and FE_SIX outside the covenant's and the song's groups on the cached load); THE CAUSE READ IN THE CACHE'S INDEX FILES (%(IDX)s) — the new runner harvested alone at the tape step's warm run beside restored neighbours: the bindings assignments, the objects restored copies under no top-level name, the records plain hashes; ONE background job (ch33b_tail_chain.sh): the cache cleared whole, the chain's second pass — its first launch --from probes STOPPED at %(ABORT_S)d s (the eleven suites at once on a cold cache — a race), the cache cleared again, relaunched FROM THE TAPE (20b's form) — green through the positions (%(CHAIN2)d s; the probe suites all full — the cache probe %(IC2)s, %(C6OK)s; the register gate strict %(REG60)s; the positions %(POS)s) and RED at the checkpoint probes' K1 (%(CK2)s — the probe's beyond_the_tape reads single-quoted case sources alone and returned %(BEYOND1)s; chapter 33's %(DQ)d carry an apostrophe and sit in double quotes: its world held no chapter 33 line, %(DIFFS)s; the positions' finals MATCH — read by hand in ch33b_k1_diag.py, K1's steps repeated), the reader widened to either quote (patch_k1_probe_ch33b.py), THE THIRD PASS from the checkpoint ALL GREEN (%(CHAIN3)d s; the checkpoint probes %(CK3)s; the sweep %(SWEEP)s — this runner %(SWT)s s; the journal unmoved; the two %(CHAIN_S)d s over %(NCHAIN)d steps); the records written (the map's AS BUILT from a template filled from the prints — the departures 1-14, the lessons 1-16), the forms copied (RUN A's, RUN B's and the tail's), the message built (21 folded beneath 21b). THE LESSONS BEYOND RUN B'S TEN: a blessing compiles as statuses on the fathers' ledgers, no heaven entry, no reuse, no new entity; the register test looks back ten verses from each cited verse — an act needs the chapter's own narrative verb; the gate's pointers are the gate's to demand — the readback rows carry the forward and the run citations; A NEW RUNNER IS HARVESTED ALONE BESIDE CACHED NEIGHBOURS — the import cache is cleared whole before the chain at EVERY compile sitting (18b's lesson 11 widened to the new runner; the cause read in the cache's own index files — an alias a [hash, module, name] record, a copy a bare hash); A COLD CACHE UNDER THE PROBES STEP IS A RACE — a pass after a clear runs FROM THE TAPE, never --from probes; a wrong launch stopped at once, the cache cleared again; the recovery page's cap asserted before the write; the tail job one wrapper, its facts module PARTIAL while it runs; A TAPE LITERAL'S QUOTE IS repr's CHOICE — a reader of the tape section takes either quote, and a checkpoint diverging in a probe's world alone is that world to read first, by hand. %(NSTEP)d timed steps, %(TSEC)d machine seconds. UNCOMMITTED with 21 since 472d2a3. NEXT on his word: the commit; then 22 (the reading of 34 — Moses' death, the three gifts' daemon at 34:5, the pointers 33:21 -> 34:6 and 34:1-4 paid, Tosefta Sotah 4:4 read; lean; DEUTERONOMY'S LAST) after a compaction.\n" % D)
debt = rd(DEBT); anchor = ' 21b (the compile of 33): next.'; assert debt.count(anchor) == 1 and ' (15) sitting' not in debt and debt.count(' (14) sitting 21 (') == 1, debt.count(anchor); debt2 = debt.replace(anchor, DEBT_LINE)
HEB = re.compile('[%s-%s]' % (chr(0x5d0), chr(0x5ea)))
for t in (ASB, NOTE242, DEBT_LINE, mw2[len(mw):], SEC2, NEWL, SHORT): assert not HEB.search(t), 'no Hebrew script in the new texts'
for t in (ASB, NOTE242, DEBT_LINE, mw2, rec2, mm2): assert os.path.expanduser('~') not in t and SP not in t, 'a home or scratch path'
assert len(rec2.encode()) <= 10240 and len(mm2.encode()) < 17000, (len(rec2.encode()), len(mm2.encode()))
LINT = {}
for p in (MAP, SD, REC, MM, MW, DEBT):
    r = subprocess.run(['python3', f'{ROOT}/logic/solo_tools/gloss_lint.py', p], capture_output=True, text=True); LINT[os.path.basename(p)] = int(re.search(r'(\d+) flag', r.stdout).group(1))
print('THE RECORDS %s: the AS BUILT %d bytes; the NOTE %d; the recovery page %d; MEMORY.md %d (was %d); the walk note %d; the debt line %d; the lints before %s' % ('CHECKED' if CHECK else 'WRITTEN', len(ASB.encode()), len(NOTE242.encode()), len(rec2.encode()), len(mm2.encode()), len(mm.encode()), len(mw2.encode()), len(DEBT_LINE.encode()), LINT))
if not CHECK:
    open(MAP, 'w', encoding='utf-8').write(m.rstrip('\n') + ASB)
    open(SD, 'w', encoding='utf-8').write(sd.rstrip('\n') + NOTE242 + '\n')
    open(REC, 'w', encoding='utf-8').write(rec2); open(MM, 'w', encoding='utf-8').write(mm2); open(MW, 'w', encoding='utf-8').write(mw2); open(DEBT, 'w', encoding='utf-8').write(debt2)
    L2 = {}
    for p in (MAP, SD, REC, MM, MW, DEBT):
        r = subprocess.run(['python3', f'{ROOT}/logic/solo_tools/gloss_lint.py', p], capture_output=True, text=True); L2[os.path.basename(p)] = int(re.search(r'(\d+) flag', r.stdout).group(1))
    assert L2 == LINT, (LINT, L2)
    print('THE RECORDS WRITTEN — every lint unmoved:', L2)
